(function(L){
  'use strict';
  const E=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const symbols={linear:'[ ]','stack-queue':'↕',hash:'#',trees:'⋔',heaps:'△',graphs:'◇',sets:'∪',stl:'<>',methods:'→',advanced:'∑',search:'⌕',sorting:'⇅',traversal:'⌘','tree-traversal':'⑂',graph:'⋈',techniques:'↔',dp:'▦',greedy:'↗',strings:'Aa',math:'%'};
  const card=group=>'<a class="category-card" data-group="'+E(group.id)+'" href="'+group.section+'/'+group.id+'/index.html"><div class="card-top"><span class="group-icon '+(group.section==='structures'?'structure':'')+'" aria-hidden="true">'+E(symbols[group.id]||'⌘')+'</span><span class="card-number">'+group.number+'</span></div><h3>'+E(group.title)+'</h3><p>'+E(group.description)+'</p><div class="topic-tags">'+(group.tags||group.entries.slice(0,3).map(x=>x.title)).map(title=>'<span>'+E(title)+'</span>').join('')+'</div><div class="card-bottom"><span>'+(group.guide?'C++ 专题 · '+group.entries.length+' 个关联演示':group.entries.length+' 个主题 · 3 种语言')+'</span><span class="arrow" aria-hidden="true">↗</span></div></a>';
  document.getElementById('structure-grid').innerHTML=L.catalogGroups.filter(x=>x.section==='structures').map(card).join('');document.getElementById('algorithm-grid').innerHTML=L.catalogGroups.filter(x=>x.section==='algorithms').map(card).join('');
  const header=document.querySelector('.site-header');
  const updateHeader=()=>header.classList.toggle('is-scrolled',window.scrollY>32);
  updateHeader();window.addEventListener('scroll',updateHeader,{passive:true});window.addEventListener('pageshow',updateHeader);
  const input=document.getElementById('search-input'),results=document.getElementById('search-results'),normal=document.getElementById('catalog-content');input.addEventListener('input',()=>{const query=input.value.trim().toLowerCase();normal.classList.toggle('hidden',!!query);results.classList.toggle('hidden',!query);if(!query){results.innerHTML='';return;}const matches=L.searchItems.filter(x=>(x.title+' '+x.id+' '+x.groupTitle+' '+x.description).toLowerCase().includes(query));document.getElementById('search-count').textContent=matches.length+' 个匹配';results.innerHTML=matches.length?matches.map(x=>'<a class="result-row" href="'+x.path+'" target="_blank" rel="noopener"><b>'+E(x.title)+' ↗</b><small>'+E(x.groupTitle)+' · '+E(x.description)+'</small></a>').join(''):'<p class="empty-search">没有找到对应算法，可以尝试“二分”“BFS”或“背包”。</p>';});
})(AlgoLab);
